export function getProductDeliveryLocations(
  productId: ProductId,
): readonly ProductDeliveryLocation[] {
  const index: Partial<Record<ProductId, ProductDeliveryLocation[]>> =
    productDeliveries;

  return index[productId] ?? [];
}
